/* ==========================================================================
   DESIGN SYSTEM & CUSTOM PROPERTIES (Vanilla CSS)
   ========================================================================== */

:root {
    /* Fonts */
    --font-primary: 'Inter', sans-serif;
    --font-display: 'Outfit', sans-serif;

    /* Theme Variables - Dark Theme (Default) */
    --bg-main: #0a0e17;
    --bg-card: #131a26;
    --bg-nav: rgba(10, 14, 23, 0.75);
    --bg-input: #1a2333;

    --color-primary: #3b82f6; /* Premium Blue */
    --color-primary-glow: rgba(59, 130, 246, 0.15);
    --color-accent: #6366f1; /* Indigo Accent */
    --color-accent-glow: rgba(99, 102, 241, 0.2);

    --text-main: #f1f5f9;
    --text-muted: #94a3b8;
    --text-inverse: #0f172a;

    --border-color: #1e293b;
    --border-hover: #334155;

    /* Shadows */
    --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.2);
    --shadow-md: 0 10px 30px rgba(0, 0, 0, 0.3);
    --shadow-lg: 0 20px 40px rgba(0, 0, 0, 0.4);
    --shadow-glow: 0 0 25px rgba(59, 130, 246, 0.25);

    /* Layout Constants */
    --max-width: 1200px;
    --border-radius-sm: 8px;
    --border-radius-md: 16px;
    --border-radius-lg: 24px;
    --transition-speed: 0.3s;
}

/* Light Theme Variables Override */
body.light-theme {
    --bg-main: #f8fafc;
    --bg-card: #ffffff;
    --bg-nav: rgba(248, 250, 252, 0.75);
    --bg-input: #f1f5f9;

    --color-primary: #1d4ed8; /* Deeper Blue for Contrast */
    --color-primary-glow: rgba(29, 78, 216, 0.1);
    --color-accent: #4f46e5;
    --color-accent-glow: rgba(79, 70, 229, 0.15);

    --text-main: #0f172a;
    --text-muted: #475569;
    --text-inverse: #ffffff;

    --border-color: #e2e8f0;
    --border-hover: #cbd5e1;

    --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.05);
    --shadow-md: 0 10px 30px rgba(0, 0, 0, 0.08);
    --shadow-lg: 0 20px 40px rgba(0, 0, 0, 0.12);
    --shadow-glow: 0 0 25px rgba(29, 78, 216, 0.15);
}

/* ==========================================================================
   RESET & BASE STYLES
   ========================================================================== */

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
    scroll-padding-top: 80px; /* Offset for sticky nav */
}

body {
    font-family: var(--font-primary);
    background-color: var(--bg-main);
    color: var(--text-main);
    line-height: 1.6;
    overflow-x: hidden;
    transition: background-color var(--transition-speed) ease, color var(--transition-speed) ease;
}

main {
    position: relative;
    z-index: 1;
}

a {
    color: inherit;
    text-decoration: none;
    transition: color var(--transition-speed) ease, transform var(--transition-speed) ease;
}

button, input, textarea {
    font-family: inherit;
    font-size: inherit;
    border: none;
    outline: none;
    background: none;
}

button {
    cursor: pointer;
}

/* ==========================================================================
   REUSABLE UTILITIES & LAYOUTS
   ========================================================================== */

.section-container {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 0 24px;
}

.section-padding {
    padding: 100px 0;
}

.text-center {
    text-align: center;
}

.badge {
    display: inline-block;
    padding: 6px 14px;
    font-size: 0.85rem;
    font-weight: 600;
    font-family: var(--font-display);
    color: var(--color-primary);
    background-color: var(--color-primary-glow);
    border: 1px solid rgba(59, 130, 246, 0.3);
    border-radius: 50px;
    margin-bottom: 20px;
}

.section-header {
    margin-bottom: 60px;
}

.section-pre {
    font-family: var(--font-display);
    color: var(--color-primary);
    font-weight: 600;
    font-size: 0.95rem;
    text-transform: uppercase;
    letter-spacing: 2px;
    margin-bottom: 8px;
}

.section-title {
    font-family: var(--font-display);
    font-size: 2.5rem;
    font-weight: 700;
    position: relative;
}

.section-underline {
    width: 60px;
    height: 4px;
    background: linear-gradient(90deg, var(--color-primary), var(--color-accent));
    margin: 15px auto 0 auto;
    border-radius: 2px;
}

/* ==========================================================================
   BUTTONS
   ========================================================================== */

.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 14px 28px;
    font-family: var(--font-display);
    font-weight: 600;
    border-radius: var(--border-radius-sm);
    transition: all var(--transition-speed) cubic-bezier(0.4, 0, 0.2, 1);
    font-size: 0.95rem;
}

.btn-primary {
    background: linear-gradient(135deg, var(--color-primary), var(--color-accent));
    color: var(--text-inverse);
    box-shadow: 0 4px 15px rgba(59, 130, 246, 0.35);
}

.btn-primary:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 25px rgba(59, 130, 246, 0.5), var(--shadow-glow);
}

.btn-secondary {
    background-color: transparent;
    color: var(--text-main);
    border: 2px solid var(--border-color);
}

.btn-secondary:hover {
    border-color: var(--color-primary);
    background-color: var(--color-primary-glow);
    transform: translateY(-3px);
}

/* ==========================================================================
   HEADER & NAVIGATION BAR
   ========================================================================== */

.main-header {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    z-index: 1000;
    background-color: var(--bg-nav);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--border-color);
    transition: all var(--transition-speed) ease;
}

.main-header.scrolled {
    padding: 10px 0;
    box-shadow: var(--shadow-sm);
}

.nav-container {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 20px 24px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-family: var(--font-display);
    font-size: 1.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.logo-accent {
    color: var(--color-primary);
}

.nav-menu ul {
    display: flex;
    list-style: none;
    gap: 32px;
    align-items: center;
}

.nav-link {
    font-weight: 500;
    font-size: 0.95rem;
    color: var(--text-muted);
    position: relative;
    padding: 6px 0;
}

.nav-link:hover, .nav-link.active {
    color: var(--text-main);
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--color-primary);
    transition: width var(--transition-speed) ease;
}

.nav-link:hover::after, .nav-link.active::after {
    width: 100%;
}

.btn-nav {
    padding: 8px 18px;
    border: 1px solid var(--color-primary);
    border-radius: 6px;
    color: var(--color-primary) !important;
}

.btn-nav::after {
    display: none;
}

.btn-nav:hover {
    background-color: var(--color-primary);
    color: var(--text-inverse) !important;
}

.nav-actions {
    display: flex;
    align-items: center;
    gap: 16px;
}

/* Theme Toggle Button */
.theme-toggle-btn {
    color: var(--text-muted);
    width: 40px;
    height: 40px;
    border-radius: 50px;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: var(--bg-input);
    border: 1px solid var(--border-color);
    transition: all var(--transition-speed) ease;
}

.theme-toggle-btn:hover {
    color: var(--text-main);
    border-color: var(--color-primary);
    transform: scale(1.05);
}

.theme-toggle-btn svg {
    width: 20px;
    height: 20px;
}

/* Hide sun in dark mode and moon in light mode */
body.dark-theme .moon-icon { display: none; }
body.light-theme .sun-icon { display: none; }

/* Mobile Menu Toggle */
.mobile-menu-toggle {
    display: none;
    flex-direction: column;
    gap: 6px;
    width: 30px;
}

.mobile-menu-toggle .bar {
    width: 100%;
    height: 2.5px;
    background-color: var(--text-main);
    border-radius: 2px;
    transition: all 0.3s ease;
}

/* ==========================================================================
   HERO SECTION
   ========================================================================== */

.hero-section {
    padding-top: 160px;
    padding-bottom: 80px;
    position: relative;
}

.hero-bg-glow {
    position: absolute;
    top: 0;
    right: 10%;
    width: 450px;
    height: 450px;
    background: radial-gradient(circle, rgba(59,130,246,0.12) 0%, rgba(99,102,241,0.06) 50%, rgba(0,0,0,0) 100%);
    z-index: 0;
    pointer-events: none;
    border-radius: 50%;
}

.hero-container {
    display: grid;
    grid-template-columns: 1.2fr 0.8fr;
    gap: 60px;
    align-items: center;
    position: relative;
    z-index: 2;
}

.hero-content h1 {
    font-family: var(--font-display);
    font-size: 4rem;
    font-weight: 800;
    line-height: 1.1;
    margin-bottom: 12px;
    letter-spacing: -1.5px;
    background: linear-gradient(135deg, var(--text-main) 30%, var(--text-muted) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.hero-subtitle {
    font-family: var(--font-display);
    font-size: 1.25rem;
    font-weight: 500;
    color: var(--color-primary);
    margin-bottom: 24px;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 10px;
}

.hero-subtitle .bullet {
    color: var(--text-muted);
    font-size: 0.8rem;
    opacity: 0.5;
}

.hero-description {
    font-size: 1.1rem;
    color: var(--text-muted);
    margin-bottom: 40px;
    max-width: 600px;
}

.hero-actions {
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
}

.hero-visual {
    display: flex;
    justify-content: center;
    position: relative;
}

.profile-frame {
    position: relative;
    width: 320px;
    height: 320px;
    border-radius: var(--border-radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-lg);
}

.profile-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    filter: grayscale(10%) contrast(105%);
    transition: transform var(--transition-speed) ease;
}

.profile-frame:hover .profile-img {
    transform: scale(1.05);
}

.frame-border {
    position: absolute;
    top: 10px;
    left: 10px;
    right: 10px;
    bottom: 10px;
    border: 2px solid rgba(255, 255, 255, 0.1);
    border-radius: calc(var(--border-radius-lg) - 10px);
    pointer-events: none;
    transition: all var(--transition-speed) ease;
}

.profile-frame:hover .frame-border {
    border-color: var(--color-primary);
    top: 15px;
    left: 15px;
    right: 15px;
    bottom: 15px;
}

/* Quick Metrics Bar */
.metrics-bar-wrapper {
    margin-top: 80px;
    width: 100%;
    position: relative;
    z-index: 2;
}

.metrics-container {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 0 24px;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 24px;
}

.metric-card {
    background-color: var(--bg-card);
    border: 1px solid var(--border-color);
    padding: 24px;
    border-radius: var(--border-radius-md);
    text-align: center;
    box-shadow: var(--shadow-sm);
    transition: all var(--transition-speed) ease;
}

.metric-card:hover {
    border-color: var(--color-primary);
    transform: translateY(-5px);
    box-shadow: var(--shadow-md);
}

.metric-value {
    font-family: var(--font-display);
    font-size: 2.2rem;
    font-weight: 800;
    color: var(--color-primary);
    margin-bottom: 4px;
    background: linear-gradient(135deg, var(--color-primary), var(--color-accent));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.metric-label {
    font-size: 0.85rem;
    color: var(--text-muted);
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 1px;
}

/* ==========================================================================
   ABOUT ME SECTION
   ========================================================================== */

.about-grid {
    display: grid;
    grid-template-columns: 1.1fr 0.9fr;
    gap: 80px;
    align-items: flex-start;
}

.about-text h3 {
    font-family: var(--font-display);
    font-size: 1.8rem;
    font-weight: 700;
    margin-bottom: 20px;
    line-height: 1.3;
}

.about-text p {
    color: var(--text-muted);
    margin-bottom: 20px;
}

.education-block {
    margin-top: 40px;
}

.education-block h4 {
    font-family: var(--font-display);
    font-size: 1.25rem;
    font-weight: 700;
    margin-bottom: 24px;
    position: relative;
    padding-left: 12px;
}

.education-block h4::before {
    content: '';
    position: absolute;
    left: 0;
    top: 4px;
    height: 16px;
    width: 4px;
    background-color: var(--color-primary);
    border-radius: 2px;
}

.edu-item {
    position: relative;
    padding-left: 24px;
    border-left: 2px solid var(--border-color);
    padding-bottom: 28px;
}

.edu-item:last-child {
    border-left: 2px solid transparent;
    padding-bottom: 0;
}

.edu-item::after {
    content: '';
    position: absolute;
    left: -7px;
    top: 5px;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background-color: var(--bg-main);
    border: 2px solid var(--color-primary);
}

.edu-meta {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 4px;
    flex-wrap: wrap;
    gap: 8px;
}

.edu-degree {
    font-weight: 600;
    font-size: 1rem;
}

.edu-date {
    font-size: 0.85rem;
    color: var(--color-primary);
    font-weight: 600;
    background-color: var(--color-primary-glow);
    padding: 2px 10px;
    border-radius: 50px;
}

.edu-school {
    font-weight: 500;
    font-size: 0.9rem;
    color: var(--text-main);
    margin-bottom: 8px;
}

.edu-desc {
    font-size: 0.9rem !important;
    margin-bottom: 0 !important;
}

/* Quote and Highlights Right Panel */
.about-quote-card {
    background-color: var(--bg-card);
    border: 1px solid var(--border-color);
    padding: 30px;
    border-radius: var(--border-radius-md);
    margin-bottom: 40px;
    position: relative;
    box-shadow: var(--shadow-sm);
}

.quote-icon {
    width: 36px;
    height: 36px;
    color: var(--color-primary);
    opacity: 0.15;
    position: absolute;
    top: 20px;
    left: 20px;
}

.about-quote-card p {
    position: relative;
    z-index: 2;
    font-style: italic;
    color: var(--text-main);
    font-size: 1.05rem;
    line-height: 1.5;
}

.highlights-grid {
    display: flex;
    flex-direction: column;
    gap: 24px;
}

.highlight-item {
    display: flex;
    gap: 20px;
    align-items: flex-start;
}

.hl-icon {
    width: 48px;
    height: 48px;
    border-radius: var(--border-radius-sm);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.hl-icon svg {
    width: 24px;
    height: 24px;
}

.advertising-hl {
    background-color: rgba(239, 68, 68, 0.1);
    color: #ef4444;
}

.ai-hl {
    background-color: rgba(168, 85, 247, 0.1);
    color: #a855f7;
}

.tech-hl {
    background-color: rgba(16, 185, 129, 0.1);
    color: #10b981;
}

.hl-content h5 {
    font-family: var(--font-display);
    font-size: 1.05rem;
    font-weight: 600;
    margin-bottom: 4px;
}

.hl-content p {
    font-size: 0.9rem;
    color: var(--text-muted);
}

/* ==========================================================================
   CORE SKILLS SECTION
   ========================================================================== */

.skills-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 24px;
}

.skill-card {
    background-color: var(--bg-card);
    border: 1px solid var(--border-color);
    padding: 36px;
    border-radius: var(--border-radius-md);
    box-shadow: var(--shadow-sm);
    transition: all var(--transition-speed) ease;
}

.skill-card:hover {
    border-color: var(--color-primary);
    transform: translateY(-6px);
    box-shadow: var(--shadow-md);
}

.skill-card-header {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 24px;
}

.skill-icon {
    width: 46px;
    height: 46px;
    border-radius: 50px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.skill-icon svg {
    width: 22px;
    height: 22px;
}

.skill-icon.advertising { background-color: rgba(239, 68, 68, 0.1); color: #ef4444; }
.skill-icon.marketing { background-color: rgba(245, 158, 11, 0.1); color: #f59e0b; }
.skill-icon.analytics { background-color: rgba(59, 130, 246, 0.1); color: #3b82f6; }
.skill-icon.ai-tools { background-color: rgba(168, 85, 247, 0.1); color: #a855f7; }
.skill-icon.development { background-color: rgba(16, 185, 129, 0.1); color: #10b981; }

.skill-card h3 {
    font-family: var(--font-display);
    font-size: 1.3rem;
    font-weight: 700;
}

.skill-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.skill-list li {
    font-size: 0.95rem;
    color: var(--text-muted);
    position: relative;
    padding-left: 20px;
}

.skill-list li::before {
    content: '→';
    position: absolute;
    left: 0;
    top: -1px;
    color: var(--color-primary);
    font-weight: bold;
}

/* ==========================================================================
   WORK EXPERIENCE TIMELINE
   ========================================================================== */

.timeline {
    position: relative;
    max-width: 900px;
    margin: 0 auto;
}

.timeline::after {
    content: '';
    position: absolute;
    width: 2px;
    background-color: var(--border-color);
    top: 20px;
    bottom: 20px;
    left: 40px;
}

.timeline-item {
    position: relative;
    padding-left: 90px;
    margin-bottom: 50px;
}

.timeline-item:last-child {
    margin-bottom: 0;
}

.timeline-marker {
    position: absolute;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background-color: var(--bg-main);
    border: 4px solid var(--color-primary);
    left: 31px;
    top: 22px;
    z-index: 2;
    transition: all var(--transition-speed) ease;
}

.timeline-item:hover .timeline-marker {
    transform: scale(1.3);
    background-color: var(--color-primary);
    box-shadow: 0 0 10px var(--color-primary);
}

.timeline-content {
    background-color: var(--bg-card);
    border: 1px solid var(--border-color);
    padding: 40px;
    border-radius: var(--border-radius-md);
    box-shadow: var(--shadow-sm);
    transition: all var(--transition-speed) ease;
}

.timeline-content:hover {
    border-color: var(--color-primary);
    box-shadow: var(--shadow-md);
}

.timeline-date {
    display: inline-block;
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--color-primary);
    background-color: var(--color-primary-glow);
    padding: 4px 12px;
    border-radius: 50px;
    margin-bottom: 16px;
}

.timeline-content h3 {
    font-family: var(--font-display);
    font-size: 1.6rem;
    font-weight: 700;
    margin-bottom: 4px;
}

.timeline-company {
    font-weight: 600;
    font-size: 1.05rem;
    color: var(--text-main);
    margin-bottom: 20px;
}

.timeline-location {
    font-weight: 400;
    font-size: 0.9rem;
    color: var(--text-muted);
}

.timeline-intro {
    font-size: 1rem;
    font-weight: 500;
    color: var(--text-main);
    margin-bottom: 16px;
}

.experience-bullets {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-bottom: 28px;
}

.experience-bullets li {
    font-size: 0.95rem;
    color: var(--text-muted);
    position: relative;
    padding-left: 20px;
}

.experience-bullets li::before {
    content: '•';
    position: absolute;
    left: 0;
    color: var(--color-primary);
    font-size: 1.5rem;
    line-height: 1;
    top: -2px;
}

.timeline-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
}

.tech-tag {
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--text-muted);
    background-color: var(--bg-input);
    border: 1px solid var(--border-color);
    padding: 4px 12px;
    border-radius: 4px;
}

/* ==========================================================================
   WORK & CASE STUDIES FILTERABLE GRID
   ========================================================================== */

.work-tabs {
    display: flex;
    justify-content: center;
    gap: 16px;
    margin-bottom: 48px;
    flex-wrap: wrap;
}

.tab-btn {
    padding: 10px 24px;
    border-radius: 50px;
    font-family: var(--font-display);
    font-weight: 600;
    font-size: 0.95rem;
    color: var(--text-muted);
    background-color: var(--bg-card);
    border: 1px solid var(--border-color);
    transition: all var(--transition-speed) ease;
}

.tab-btn:hover {
    color: var(--text-main);
    border-color: var(--border-hover);
}

.tab-btn.active {
    color: var(--text-inverse);
    background-color: var(--color-primary);
    border-color: var(--color-primary);
    box-shadow: 0 4px 12px rgba(59, 130, 246, 0.2);
}

.work-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 30px;
}

.work-card {
    background-color: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: var(--border-radius-md);
    overflow: hidden;
    box-shadow: var(--shadow-sm);
    transition: all var(--transition-speed) cubic-bezier(0.4, 0, 0.2, 1);
    display: flex;
    flex-direction: column;
    height: 100%;
}

.work-card:hover {
    border-color: var(--color-primary);
    transform: translateY(-8px);
    box-shadow: var(--shadow-lg);
}

.work-image-wrapper {
    position: relative;
    height: 220px;
    overflow: hidden;
    background-color: var(--bg-input);
}

.work-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-speed) ease;
}

.work-card:hover .work-img {
    transform: scale(1.05);
}

.work-overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: rgba(10, 14, 23, 0.7);
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    transition: opacity var(--transition-speed) ease;
}

.work-card:hover .work-overlay {
    opacity: 1;
}

.btn-view-project {
    color: var(--text-inverse);
    background-color: var(--color-primary);
    padding: 10px 20px;
    border-radius: var(--border-radius-sm);
    font-weight: 600;
    font-size: 0.9rem;
    font-family: var(--font-display);
    box-shadow: var(--shadow-sm);
}

.work-image-placeholder {
    height: 220px;
    background: linear-gradient(135deg, var(--bg-card), var(--bg-input));
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    position: relative;
    border-bottom: 1px solid var(--border-color);
}

.tech-icon-glow {
    font-size: 3rem;
    color: var(--color-primary);
    filter: drop-shadow(0 0 10px rgba(59, 130, 246, 0.3));
    margin-bottom: 8px;
}

.tech-icon-glow svg {
    color: var(--color-primary);
}

.placeholder-tag {
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--text-muted);
    letter-spacing: 0.5px;
}

.work-info {
    padding: 28px;
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.work-tag {
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    color: var(--color-primary);
    letter-spacing: 1.5px;
    margin-bottom: 10px;
}

.work-info h3 {
    font-family: var(--font-display);
    font-size: 1.35rem;
    font-weight: 700;
    margin-bottom: 12px;
}

.work-info p {
    color: var(--text-muted);
    font-size: 0.95rem;
    margin-bottom: 24px;
    flex-grow: 1;
}

.work-tech {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: auto;
}

.work-tech span {
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--text-main);
    background-color: var(--bg-input);
    padding: 4px 10px;
    border-radius: 4px;
}

/* ==========================================================================
   CERTIFICATIONS SECTION WITH LIVE SEARCH & TAB FILTER
   ========================================================================== */

.cert-controls {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 24px;
    margin-bottom: 40px;
    flex-wrap: wrap;
}

.search-box {
    position: relative;
    flex-grow: 1;
    max-width: 450px;
}

.search-box input {
    width: 100%;
    background-color: var(--bg-card);
    border: 1px solid var(--border-color);
    padding: 12px 18px 12px 46px;
    border-radius: var(--border-radius-sm);
    color: var(--text-main);
    transition: all var(--transition-speed) ease;
}

.search-box input::placeholder {
    color: var(--text-muted);
}

.search-box input:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 10px rgba(59, 130, 246, 0.15);
}

.search-icon {
    width: 20px;
    height: 20px;
    position: absolute;
    left: 16px;
    top: 13px;
    color: var(--text-muted);
    pointer-events: none;
}

.cert-tabs {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
}

.cert-tab-btn {
    padding: 8px 18px;
    font-size: 0.85rem;
    font-weight: 600;
    border-radius: var(--border-radius-sm);
    background-color: var(--bg-card);
    border: 1px solid var(--border-color);
    color: var(--text-muted);
    transition: all var(--transition-speed) ease;
}

.cert-tab-btn:hover {
    color: var(--text-main);
}

.cert-tab-btn.active {
    background-color: var(--color-primary-glow);
    color: var(--color-primary);
    border-color: var(--color-primary);
}

.cert-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 20px;
}

.cert-card {
    background-color: var(--bg-card);
    border: 1px solid var(--border-color);
    padding: 24px;
    border-radius: var(--border-radius-sm);
    box-shadow: var(--shadow-sm);
    transition: all var(--transition-speed) ease;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

.cert-card:hover {
    border-color: var(--color-primary);
    transform: translateY(-3px);
    box-shadow: var(--shadow-md);
}

.cert-badge {
    align-self: flex-start;
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 2px 8px;
    border-radius: 4px;
    margin-bottom: 12px;
}

.cert-badge.ai { background-color: rgba(168, 85, 247, 0.1); color: #a855f7; }
.cert-badge.data { background-color: rgba(59, 130, 246, 0.1); color: #3b82f6; }
.cert-badge.cloud { background-color: rgba(16, 185, 129, 0.1); color: #10b981; }
.cert-badge.marketing { background-color: rgba(245, 158, 11, 0.1); color: #f59e0b; }

.cert-card h3 {
    font-family: var(--font-display);
    font-size: 1.05rem;
    font-weight: 700;
    line-height: 1.4;
    margin-bottom: 16px;
    color: var(--text-main);
    flex-grow: 1;
}

.cert-meta {
    display: flex;
    justify-content: space-between;
    font-size: 0.8rem;
    color: var(--text-muted);
    border-top: 1px solid var(--border-color);
    padding-top: 12px;
    flex-wrap: wrap;
    gap: 4px;
}

.cert-issuer {
    font-weight: 500;
}

.cert-date {
    font-weight: 600;
}

/* ==========================================================================
   CREATIVE GALLERY SECTION
   ========================================================================== */

.gallery-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 24px;
}

.gallery-item {
    border-radius: var(--border-radius-md);
    overflow: hidden;
    box-shadow: var(--shadow-sm);
    transition: all var(--transition-speed) ease;
}

.gallery-item:hover {
    transform: scale(1.02);
    box-shadow: var(--shadow-md);
}

.gallery-image-wrapper {
    position: relative;
    height: 240px;
    overflow: hidden;
    background-color: var(--bg-card);
}

.gallery-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    transition: transform var(--transition-speed) ease;
}

.gallery-item:hover .gallery-img {
    transform: scale(1.05);
}

.gallery-overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: linear-gradient(to top, rgba(10, 14, 23, 0.9) 20%, rgba(10, 14, 23, 0.4) 60%, rgba(10, 14, 23, 0.1) 100%);
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    padding: 24px;
    opacity: 0;
    transition: opacity var(--transition-speed) ease;
}

.gallery-item:hover .gallery-overlay {
    opacity: 1;
}

.gallery-overlay h4 {
    font-family: var(--font-display);
    font-size: 1.2rem;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 4px;
}

.gallery-overlay p {
    font-size: 0.85rem;
    color: rgba(255, 255, 255, 0.7);
    margin-bottom: 12px;
}

.btn-lightbox {
    align-self: flex-start;
    background-color: var(--color-primary);
    color: var(--text-inverse);
    width: 36px;
    height: 36px;
    border-radius: 50px;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: var(--shadow-sm);
    transition: transform 0.2s ease;
}

.btn-lightbox:hover {
    transform: scale(1.1);
}

.btn-lightbox svg {
    width: 16px;
    height: 16px;
}

/* ==========================================================================
   CONTACT SECTION
   ========================================================================== */

.contact-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 60px;
    align-items: start;
}

.contact-info-block h3 {
    font-family: var(--font-display);
    font-size: 1.8rem;
    font-weight: 700;
    margin-bottom: 20px;
    line-height: 1.3;
}

.contact-info-block p {
    color: var(--text-muted);
    margin-bottom: 36px;
}

.contact-methods {
    display: flex;
    flex-direction: column;
    gap: 20px;
    margin-bottom: 40px;
}

.contact-method-card {
    background-color: var(--bg-card);
    border: 1px solid var(--border-color);
    padding: 20px;
    border-radius: var(--border-radius-sm);
    display: flex;
    align-items: center;
    gap: 20px;
    box-shadow: var(--shadow-sm);
    transition: all var(--transition-speed) ease;
}

.contact-method-card:hover {
    border-color: var(--color-primary);
    transform: translateX(5px);
    box-shadow: var(--shadow-md);
}

.method-icon {
    width: 48px;
    height: 48px;
    border-radius: 50px;
    background-color: var(--color-primary-glow);
    color: var(--color-primary);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.method-icon svg {
    width: 20px;
    height: 20px;
}

.method-details {
    display: flex;
    flex-direction: column;
}

.method-label {
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 1px;
}

.method-value {
    font-weight: 600;
    font-size: 1rem;
    color: var(--text-main);
}

.social-links-wrapper h4 {
    font-family: var(--font-display);
    font-size: 1.1rem;
    font-weight: 700;
    margin-bottom: 16px;
}

.social-icons {
    display: flex;
    gap: 12px;
}

.social-icons a {
    width: 44px;
    height: 44px;
    border-radius: 50px;
    background-color: var(--bg-card);
    border: 1px solid var(--border-color);
    color: var(--text-muted);
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all var(--transition-speed) ease;
}

.social-icons a:hover {
    color: var(--text-main);
    border-color: var(--color-primary);
    transform: translateY(-3px);
}

.social-icons svg {
    width: 18px;
    height: 18px;
}

/* Contact Form */
.contact-form-card {
    background-color: var(--bg-card);
    border: 1px solid var(--border-color);
    padding: 40px;
    border-radius: var(--border-radius-md);
    box-shadow: var(--shadow-sm);
}

.form-group {
    position: relative;
    margin-bottom: 24px;
}

.form-group input, .form-group textarea {
    width: 100%;
    background-color: var(--bg-input);
    border: 1px solid var(--border-color);
    padding: 16px;
    border-radius: var(--border-radius-sm);
    color: var(--text-main);
    transition: all var(--transition-speed) ease;
}

.form-group textarea {
    resize: none;
}

.form-group label {
    position: absolute;
    left: 16px;
    top: 16px;
    color: var(--text-muted);
    font-size: 0.95rem;
    transition: all 0.25s ease;
    pointer-events: none;
}

/* Float Label Animation */
.form-group input:focus ~ label,
.form-group input:not(:placeholder-shown) ~ label,
.form-group textarea:focus ~ label,
.form-group textarea:not(:placeholder-shown) ~ label {
    top: -10px;
    left: 12px;
    font-size: 0.75rem;
    font-weight: 700;
    color: var(--color-primary);
    background-color: var(--bg-card);
    padding: 2px 8px;
}

.form-group input:focus, .form-group textarea:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 10px rgba(59, 130, 246, 0.15);
}

.btn-submit {
    width: 100%;
    padding: 16px 20px;
}

/* ==========================================================================
   FOOTER
   ========================================================================== */

.main-footer {
    border-top: 1px solid var(--border-color);
    padding: 40px 0;
    background-color: var(--bg-main);
    position: relative;
    z-index: 2;
}

.footer-container {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 0 24px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
}

.footer-container p {
    font-size: 0.95rem;
    color: var(--text-muted);
}

.footer-subtext {
    font-size: 0.8rem !important;
    opacity: 0.7;
}

/* ==========================================================================
   LIGHTBOX MODAL FOR GALLERY
   ========================================================================== */

.lightbox-modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: rgba(10, 14, 23, 0.95);
    z-index: 2000;
    align-items: center;
    justify-content: center;
    opacity: 0;
    transition: opacity 0.3s ease;
}

.lightbox-modal.active {
    display: flex;
    opacity: 1;
}

.lightbox-close {
    position: absolute;
    top: 30px;
    right: 30px;
    color: #ffffff;
    font-size: 2.5rem;
    transition: transform 0.2s ease;
}

.lightbox-close:hover {
    transform: scale(1.1);
    color: var(--color-primary);
}

.lightbox-content {
    max-width: 800px;
    width: 90%;
    display: flex;
    flex-direction: column;
    gap: 20px;
    align-items: center;
}

.lightbox-content img {
    max-width: 100%;
    max-height: 70vh;
    object-fit: contain;
    border-radius: var(--border-radius-sm);
    box-shadow: var(--shadow-lg);
}

.lightbox-caption {
    text-align: center;
    color: #ffffff;
}

.lightbox-caption h4 {
    font-family: var(--font-display);
    font-size: 1.4rem;
    font-weight: 700;
    margin-bottom: 6px;
}

.lightbox-caption p {
    font-size: 0.95rem;
    color: #94a3b8;
}

/* ==========================================================================
   TOAST NOTIFICATION feedback
   ========================================================================== */

.toast-container {
    position: fixed;
    bottom: 30px;
    right: 30px;
    z-index: 3000;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.toast {
    background-color: var(--bg-card);
    border-left: 4px solid var(--color-primary);
    border-right: 1px solid var(--border-color);
    border-top: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
    color: var(--text-main);
    padding: 16px 24px;
    border-radius: 4px;
    box-shadow: var(--shadow-md);
    display: flex;
    align-items: center;
    gap: 12px;
    font-weight: 600;
    font-size: 0.9rem;
    animation: slideIn 0.3s ease forwards;
    min-width: 250px;
}

.toast.success {
    border-left-color: #10b981;
}

.toast svg {
    flex-shrink: 0;
}

/* ==========================================================================
   ANIMATIONS & SCROLL BEHAVIOR
   ========================================================================== */

@keyframes slideIn {
    from {
        transform: translateX(100%);
        opacity: 0;
    }
    to {
        transform: translateX(0);
        opacity: 1;
    }
}

@keyframes pulse {
    0% { transform: scale(1); opacity: 1; }
    50% { transform: scale(1.05); opacity: 0.9; }
    100% { transform: scale(1); opacity: 1; }
}

.animate-pulse {
    animation: pulse 3s infinite ease-in-out;
}

/* Scroll-based reveal effects using intersection observer */
.fade-in, .fade-in-up, .fade-in-left, .fade-in-right {
    opacity: 0;
    transition: all 0.8s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.fade-in-up {
    transform: translateY(30px);
}

.fade-in-left {
    transform: translateX(-40px);
}

.fade-in-right {
    transform: translateX(40px);
}

.reveal {
    opacity: 1 !important;
    transform: none !important;
}

/* Delays */
.delay-1 { transition-delay: 0.15s; }
.delay-2 { transition-delay: 0.3s; }
.delay-3 { transition-delay: 0.45s; }
.delay-4 { transition-delay: 0.6s; }

/* ==========================================================================
   MEDIA QUERIES (RESPONSIVENESS)
   ========================================================================== */

@media (max-width: 1024px) {
    .hero-container {
        gap: 40px;
    }

    .hero-content h1 {
        font-size: 3.2rem;
    }

    .about-grid, .contact-grid {
        grid-template-columns: 1fr;
        gap: 50px;
    }

    .metrics-container {
        grid-template-columns: repeat(2, 1fr);
        gap: 16px;
    }
}

@media (max-width: 768px) {
    .section-padding {
        padding: 60px 0;
    }

    .hero-container {
        grid-template-columns: 1fr;
        text-align: center;
        gap: 30px;
        padding-top: 40px;
    }

    .hero-content {
        order: 2;
    }

    .hero-subtitle {
        justify-content: center;
    }

    .hero-description {
        margin-left: auto;
        margin-right: auto;
    }

    .hero-actions {
        justify-content: center;
    }

    .hero-visual {
        order: 1;
    }

    .profile-frame {
        width: 240px;
        height: 240px;
    }

    .timeline::after {
        left: 20px;
    }

    .timeline-marker {
        left: 11px;
    }

    .timeline-item {
        padding-left: 50px;
    }

    .timeline-content {
        padding: 24px;
    }

    .timeline-company {
        margin-bottom: 12px;
    }

    .cert-controls {
        flex-direction: column;
        align-items: stretch;
    }

    .search-box {
        max-width: 100%;
    }

    /* Sticky Navigation Header changes */
    .mobile-menu-toggle {
        display: flex;
    }

    .nav-menu {
        position: absolute;
        top: 100%;
        left: -100%;
        width: 100%;
        height: calc(100vh - 80px);
        background-color: var(--bg-main);
        transition: left 0.4s cubic-bezier(0.77,0.2,0.05,1.0);
        padding: 40px 24px;
        border-top: 1px solid var(--border-color);
        box-shadow: var(--shadow-lg);
    }

    .nav-menu.active {
        left: 0;
    }

    .nav-menu ul {
        flex-direction: column;
        align-items: flex-start;
        gap: 28px;
    }

    .nav-link {
        font-size: 1.25rem;
    }

    .btn-nav {
        width: 100%;
        text-align: center;
        display: block;
        padding: 12px 0;
    }

    /* Transform mobile toggle into an 'X' when active */
    .mobile-menu-toggle.active .bar:nth-child(1) {
        transform: translateY(8.5px) rotate(45deg);
    }
    .mobile-menu-toggle.active .bar:nth-child(2) {
        opacity: 0;
    }
    .mobile-menu-toggle.active .bar:nth-child(3) {
        transform: translateY(-8.5px) rotate(-45deg);
    }
}

@media (max-width: 480px) {
    .hero-content h1 {
        font-size: 2.5rem;
    }

    .metrics-container {
        grid-template-columns: 1fr;
    }

    .edu-meta {
        flex-direction: column;
        align-items: flex-start;
    }

    .work-tabs {
        flex-direction: column;
        align-items: stretch;
    }

    .tab-btn {
        text-align: center;
    }

    .cert-tabs {
        flex-direction: column;
        align-items: stretch;
    }

    .cert-tab-btn {
        text-align: center;
    }

    .contact-form-card {
        padding: 24px;
    }
}

document.addEventListener('DOMContentLoaded', () => {
    // ==========================================================================
    // THEME TOGGLE (Light / Dark Mode)
    // ==========================================================================
    const themeToggleBtn = document.getElementById('theme-toggle');
    const body = document.body;

    // Check for saved theme preference, otherwise default to dark-theme
    const savedTheme = localStorage.getItem('portfolio-theme');

    if (savedTheme === 'light') {
        body.classList.remove('dark-theme');
        body.classList.add('light-theme');
    } else {
        body.classList.add('dark-theme');
        body.classList.remove('light-theme');
    }

    // Toggle theme on button click
    themeToggleBtn.addEventListener('click', () => {
        if (body.classList.contains('light-theme')) {
            body.classList.remove('light-theme');
            body.classList.add('dark-theme');
            localStorage.setItem('portfolio-theme', 'dark');
            showToast('Switched to Dark Mode', 'success');
        } else {
            body.classList.remove('dark-theme');
            body.classList.add('light-theme');
            localStorage.setItem('portfolio-theme', 'light');
            showToast('Switched to Light Mode', 'success');
        }
    });

    // ==========================================================================
    // MOBILE NAVIGATION MENU
    // ==========================================================================
    const mobileMenuToggle = document.getElementById('mobile-menu-toggle');
    const navMenu = document.getElementById('nav-menu');
    const navLinks = document.querySelectorAll('.nav-link');

    // Open/Close Mobile Menu
    mobileMenuToggle.addEventListener('click', () => {
        mobileMenuToggle.classList.toggle('active');
        navMenu.classList.toggle('active');
    });

    // Close Mobile Menu when a link is clicked
    navLinks.forEach(link => {
        link.addEventListener('click', () => {
            mobileMenuToggle.classList.remove('active');
            navMenu.classList.remove('active');
        });
    });

    // ==========================================================================
    // HEADER SCROLL ACTION (Add shadow & shrink padding)
    // ==========================================================================
    const header = document.getElementById('main-header');

    window.addEventListener('scroll', () => {
        if (window.scrollY > 50) {
            header.classList.add('scrolled');
        } else {
            header.classList.remove('scrolled');
        }
    });

    // ==========================================================================
    // SCROLL-SPY (Highlight active nav link based on scroll position)
    // ==========================================================================
    const sections = document.querySelectorAll('section');

    window.addEventListener('scroll', () => {
        let currentSectionId = '';

        sections.forEach(section => {
            const sectionTop = section.offsetTop - 120; // Offset for header height
            const sectionHeight = section.clientHeight;
            if (window.scrollY >= sectionTop && window.scrollY < sectionTop + sectionHeight) {
                currentSectionId = section.getAttribute('id');
            }
        });

        navLinks.forEach(link => {
            link.classList.remove('active');
            if (link.getAttribute('href') === `#${currentSectionId}`) {
                link.classList.add('active');
            }
        });
    });

    // ==========================================================================
    // REVEAL ANIMATION ON SCROLL (IntersectionObserver)
    // ==========================================================================
    const animatedElements = document.querySelectorAll('.fade-in, .fade-in-up, .fade-in-left, .fade-in-right');

    const revealOnScroll = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('reveal');
                observer.unobserve(entry.target); // Stop observing once animated
            }
        });
    }, {
        threshold: 0.15, // Trigger when 15% of the element is visible
        rootMargin: '0px 0px -50px 0px'
    });

    animatedElements.forEach(element => {
        revealOnScroll.observe(element);
    });

    // ==========================================================================
    // PROJECTS & CASE STUDIES TAB FILTER
    // ==========================================================================
    const tabButtons = document.querySelectorAll('.tab-btn');
    const workCards = document.querySelectorAll('.work-card');

    tabButtons.forEach(button => {
        button.addEventListener('click', () => {
            // Remove active class from all buttons
            tabButtons.forEach(btn => btn.classList.remove('active'));
            // Add active class to clicked button
            button.classList.add('active');

            const filterValue = button.getAttribute('data-filter');

            workCards.forEach(card => {
                const category = card.getAttribute('data-category');

                if (filterValue === 'all' || filterValue === category) {
                    // Show item with animation
                    card.style.display = 'flex';
                    setTimeout(() => {
                        card.style.opacity = '1';
                        card.style.transform = 'scale(1)';
                    }, 50);
                } else {
                    // Hide item with animation
                    card.style.opacity = '0';
                    card.style.transform = 'scale(0.95)';
                    setTimeout(() => {
                        card.style.display = 'none';
                    }, 300);
                }
            });
        });
    });

    // ==========================================================================
    // CERTIFICATIONS LIVE SEARCH & TAB FILTER
    // ==========================================================================
    const certSearchInput = document.getElementById('cert-search');
    const certTabButtons = document.querySelectorAll('.cert-tab-btn');
    const certCards = document.querySelectorAll('.cert-card');
    const certGrid = document.getElementById('cert-grid');

    // Create a "No Results" message placeholder if not exists
    let noResultsMsg = document.getElementById('no-certs-msg');
    if (!noResultsMsg) {
        noResultsMsg = document.createElement('div');
        noResultsMsg.id = 'no-certs-msg';
        noResultsMsg.style.gridColumn = '1 / -1';
        noResultsMsg.style.textAlign = 'center';
        noResultsMsg.style.padding = '40px 0';
        noResultsMsg.style.color = 'var(--text-muted)';
        noResultsMsg.style.fontFamily = 'var(--font-display)';
        noResultsMsg.style.fontWeight = '600';
        noResultsMsg.innerHTML = '<span style="font-size: 2rem; display: block; margin-bottom: 10px;">🔍</span> No certifications match your criteria.';
        noResultsMsg.style.display = 'none';
        certGrid.appendChild(noResultsMsg);
    }

    let activeCertFilter = 'all';
    let searchQuery = '';

    // Handle Category Filter click
    certTabButtons.forEach(button => {
        button.addEventListener('click', () => {
            certTabButtons.forEach(btn => btn.classList.remove('active'));
            button.classList.add('active');
            activeCertFilter = button.getAttribute('data-cert-filter');
            applyCertFilters();
        });
    });

    // Handle Search input keyup
    certSearchInput.addEventListener('input', (e) => {
        searchQuery = e.target.value.toLowerCase().trim();
        applyCertFilters();
    });

    function applyCertFilters() {
        let visibleCount = 0;

        certCards.forEach(card => {
            const category = card.getAttribute('data-category');
            const title = card.querySelector('h3').textContent.toLowerCase();
            const issuer = card.querySelector('.cert-issuer').textContent.toLowerCase();

            const matchesCategory = (activeCertFilter === 'all' || activeCertFilter === category);
            const matchesSearch = (title.includes(searchQuery) || issuer.includes(searchQuery));

            if (matchesCategory && matchesSearch) {
                card.style.display = 'flex';
                setTimeout(() => {
                    card.style.opacity = '1';
                }, 50);
                visibleCount++;
            } else {
                card.style.opacity = '0';
                card.style.display = 'none';
            }
        });

        // Toggle "No Results" message
        if (visibleCount === 0) {
            noResultsMsg.style.display = 'block';
        } else {
            noResultsMsg.style.display = 'none';
        }
    }

    // ==========================================================================
    // CREATIVE GALLERY LIGHTBOX MODAL
    // ==========================================================================
    const lightboxModal = document.getElementById('lightbox-modal');
    const lightboxImg = document.getElementById('lightbox-img');
    const lightboxTitle = document.getElementById('lightbox-title');
    const lightboxDesc = document.getElementById('lightbox-desc');
    const lightboxClose = document.getElementById('lightbox-close');
    const galleryItems = document.querySelectorAll('.gallery-item');

    galleryItems.forEach(item => {
        const image = item.querySelector('.gallery-img');
        const overlay = item.querySelector('.gallery-overlay');
        const titleText = overlay.querySelector('h4').textContent;
        const descText = overlay.querySelector('p').textContent;
        const triggerBtn = item.querySelector('.btn-lightbox');

        // Open Lightbox when clicking the expand button or the card overlay
        const openLightbox = (e) => {
            e.stopPropagation();
            lightboxImg.src = image.src;
            lightboxImg.alt = image.alt;
            lightboxTitle.textContent = titleText;
            lightboxDesc.textContent = descText;

            lightboxModal.classList.add('active');
            lightboxModal.setAttribute('aria-hidden', 'false');
            body.style.overflow = 'hidden'; // Disable page scrolling
        };

        triggerBtn.addEventListener('click', openLightbox);
        overlay.addEventListener('click', openLightbox);
    });

    // Close Lightbox
    const closeLightbox = () => {
        lightboxModal.classList.remove('active');
        lightboxModal.setAttribute('aria-hidden', 'true');
        body.style.overflow = ''; // Re-enable page scrolling
        setTimeout(() => {
            lightboxImg.src = '';
        }, 300); // Clear source after animation ends
    };

    lightboxClose.addEventListener('click', closeLightbox);

    // Close when clicking outside the content area
    lightboxModal.addEventListener('click', (e) => {
        if (e.target === lightboxModal) {
            closeLightbox();
        }
    });

    // Close on Escape Key press
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && lightboxModal.classList.contains('active')) {
            closeLightbox();
        }
    });

    // ==========================================================================
    // CONTACT FORM HANDLER WITH CUSTOM TOAST FEEDBACK
    // ==========================================================================
    const contactForm = document.getElementById('contact-form');

    contactForm.addEventListener('submit', (e) => {
        e.preventDefault();

        // Get Form Values
        const name = document.getElementById('form-name').value;
        const email = document.getElementById('form-email').value;
        const subject = document.getElementById('form-subject').value;
        const message = document.getElementById('form-message').value;

        // Perform simple validation check
        if (name && email && subject && message) {
            // Simulate API transmission / mailto launch
            console.log('Sending message:', { name, email, subject, message });

            // Display success feedback to user
            showToast(`Thank you, ${name}! Your message has been sent successfully.`, 'success');

            // Optional: trigger mailto dynamically
            // window.location.href = `mailto:aswinbinu@zohomail.in?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent("From: " + name + " (" + email + ")\n\n" + message)}`;

            // Reset Form Fields
            contactForm.reset();

            // Remove floating labels state by triggering input resets
            const inputs = contactForm.querySelectorAll('input, textarea');
            inputs.forEach(input => {
                input.blur();
            });
        } else {
            showToast('Please fill out all fields before submitting.', 'error');
        }
    });

    // ==========================================================================
    // CUSTOM TOAST NOTIFICATION UTILITY
    // ==========================================================================
    function showToast(message, type = 'success') {
        const container = document.getElementById('toast-container');

        // Create Toast element
        const toast = document.createElement('div');
        toast.className = `toast ${type}`;

        // Dynamic icons depending on toast type
        let iconSvg = '';
        if (type === 'success') {
            iconSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#10b981" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg>`;
        } else {
            iconSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#ef4444" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line></svg>`;
        }

        toast.innerHTML = `
            ${iconSvg}
            <span>${message}</span>
        `;

        container.appendChild(toast);

        // Remove toast after 4 seconds
        setTimeout(() => {
            toast.style.animation = 'slideIn 0.3s ease reverse forwards';
            setTimeout(() => {
                toast.remove();
            }, 300);
        }, 4000);
    }
});

